going to
// traverse the value changes of the other variables. The
// idcode of the other variables is from FSDB_MIN_VAR_IDCODE,
// which is 1, to (max_var_idcode - 1)
//
for (i = FSDB_MIN_VAR_IDCODE; i < max_var_idcode; i++) {
