One-hot coding style using record is not supported.
library IEEE;
use IEEE.STD_Logic_1164.all;
package RecordTypes is
type StateType is (ST_Read, ST_Write, ST_Delay);
type R1_Type is record
State: StateType;
Output:std_logic;
end record;
