The following is an example that uses the NPI Libraries Module library. Assuming a
hierarchical scope is specified by the option "-mod_scope", the program lists all the nets
in the scope and check whether a net is used in a continuous assignment. If so, the
corresponding file name and line number is printed.
demo_module_L1.cpp
include <cstdio>
// header for NPI Models: npi_init,
npi_load_design, npi_end
// header for NPI Libraries
//
// Usage: demo_module_L1.exe -mod_scope "scope_hier_name"
<novas_load_design_options>
//
{
//
// 1. parse the input argument, get mod_scope
//
string mod_scope;
npiArg arg = npi_arg_construct(argc, argv);
if( npi_arg_has_attr(arg, "-mod_scope") ) {
mod_scope = npi_arg_attr_get_value(arg, "-mod_scope", 1/*position*/);
npi_arg_remove_attr(arg, "-mod_scope");

}
printf("Usage: demo_module_L1.exe -mod_scope \"scope_hier_name\"
<novas_load_design_options>\n");
}
//
// 2. initialize NPI and load design
//
the argument is obtained from npiArg after removing the attribute
"-mod_scope"
//
int new_argc = npi_arg_get_argc(arg);
char** new_argv = npi_arg_get_argv(arg);
npi_init(new_argc, new_argv);
npi_load_design(new_argc, new_argv);
printf("Input module instance = %s\n", mod_scope.c_str());
//
// 3. get module instance net handle by NPI Libraries Module Library
//
vector<npiHandle> net_hdl_vec;
npi_mod_inst_get_net((char*)mod_scope.c_str(), net_hdl_vec);
//
// 4. iterate all net handle
//
printf("\nNet and used continuous assignment:\n");
for(int i=0; i<(int)net_hdl_vec.size(); i++) {
npiHandle net_hdl = net_hdl_vec[i];
printf("%d) %s\n", i, npi_get_str(npiName, net_hdl));
//
// get the continuous assignment from the net handle
//
npiHandle iter = npi_iterate(npiUse, net_hdl);
npiHandle cont_assign_hdl;
string fileName;
int lineNo;
while( cont_assign_hdl = npi_scan(iter) ) {
if( npi_get(npiType, cont_assign_hdl) == npiContAssign ) {
fileName = npi_get_str(npiFile, cont_assign_hdl);
lineNo
= npi_get(npiLineNo, cont_assign_hdl);
Continuous assign: %s (%d)\n", fileName.c_str(), lineNo);
}
}
}
//
// 5. leaving NPI
//

}

The program above uses npiArg (see the NPI Libraries Misc Library) first to handle the
input argument. After loading the design, the program then gets the nets of the input
module instance using the NPI Libraries Module Library API - npi_mod_inst_get_net. With
the net npiHandle, the program then iterates the continuous assignment of each net and
prints out the corresponding file name and line number.
