input OPERAND op;

input ALU_OP select;
output logic out;
output logic carry;
output wire zero;
assign zero = ( ( out == 0 ) ? 1 : 0 );
case ( select )
ADD: { carry, out } = ( ( op.a + op.b ) + op.cin );
SUB: { carry, out } = ( ( ( op.a - op.b ) - 1 ) + op.cin );
default: { carry, out } = 0;
end

